/** Map ids with a committed runtime lighting entry, in manifest build order. */
export const LIGHTING_MAPS = Object.freeze(Object.keys(DATA.maps));

/**
 * Return the committed runtime lighting for one map.
 *
 * @param {'river'|'amboy'|'gracia'|'longbeach'} mapId
 * @returns {{schema:string, mapId:string, level:string, city:string,
 *   manifest:{path:string, schema:string, bytes:number, sha256:string},
 *   sun:{direction:number[], colour:number[], intensity:number,
 *     lightObjectColour:number[], elevationDeg:number, azimuthDeg:number},
 *   sky:{colour:number[], upAxis:number[], lightObjectColour:number[],
 *     dome:{texture:string, rotation:number, intensity:number,
 *       fogColour:number[], fogCurve:number, blackHeight:number, blackSize:number}},
 *   ambient:{upNormalAmbient:number[], sh:number[], bakedColour:number[],
 *     upNormalAmbientScaled:number[],
 *     probe:{model:string, pointIndex:number, sampleIndex:number,
 *       pointPosition:number[], spawn:number[], distance:number, searchRadius:number}},
 *   fog:null|{colour:number[], depth:{density:number, nearDistance:number, scale:number},
 *     height:{height:number, density:number, falloff:number, scale:number}},
 *   missing:Array<{code:string, field:string, reason:string}>,
 *   source:string}}
 * @throws {LightingError} `invalid-map-id` for a non-string id, `unknown-map`
 *   for an id without a committed entry.
 */
export function lightingFor(mapId) {
  if (typeof mapId !== 'string') {
    throw new LightingError('invalid-map-id',
      'lightingFor: map id must be a string, got ' + typeof mapId);
  }
  const map = DATA.maps[mapId];
  if (!map) {
    throw new LightingError('unknown-map',
      'lightingFor: unknown map ' + JSON.stringify(mapId) +
      ' (use ' + LIGHTING_MAPS.join(', ') + ')');
  }
  return map;
}
